<script setup>
import { ref, computed, onMounted } from 'vue'
import { request, session } from '../api'
import { resolution, reviewLabels, reasons, dateTime } from '../domain'
import State from '../components/State.vue'
import Modal from '../components/Modal.vue'
import PostContent from '../components/PostContent.vue'
const props=defineProps({id:String})
const post=ref(null),loading=ref(true),error=ref(''),actionError=ref(''),modal=ref(''),busy=ref(false),reason=ref(''),details=ref(''),reported=ref(false),history=ref([]),historyPage=ref(1),historyTotal=ref(0),snapshot=ref(null),conflict=ref(false)
const owner=computed(()=>post.value?.author.id===session.user?.id)
async function load(){loading.value=true;error.value='';try{post.value=await request('/posts/'+props.id);conflict.value=false;if(owner.value||session.user.role==='admin')await loadHistory()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadHistory(p=1){historyPage.value=p;const data=await request(`/posts/${props.id}/reviews?page=${p}&page_size=10`);history.value=data.records;historyTotal.value=data.total}
async function change(status){if(busy.value)return;busy.value=true;actionError.value='';try{await request('/posts/'+props.id+'/resolution',{method:'PATCH',etag:post.value.etag,data:{resolution_status:status}});modal.value='';await load()}catch(e){actionError.value=e.message;conflict.value=e.status===412}finally{busy.value=false}}
async function report(){if(busy.value)return;actionError.value='';if(!reason.value||(reason.value==='other'&&!details.value.trim())||[...details.value].length>500){actionError.value='请选择原因；“其他”必须填写说明，最多 500 字。';return}busy.value=true;try{await request('/posts/'+props.id+'/reports',{method:'POST',data:{post_revision:post.value.revision,reason_type:reason.value,details:details.value||null}});reported.value=true;modal.value=''}catch(e){actionError.value=e.message}finally{busy.value=false}}
function open(name){modal.value=name;actionError.value=''}
function historyImages(r){return (r.content_snapshot.images||[]).map((_,i)=>`/api/v1/posts/${props.id}/reviews/${r.id}/images/${i}`)}
onMounted(load)
</script>
<template><a :href="owner?'#mine':'#home'" class="back">← {{owner?'我的帖子':'返回首页'}}</a><State :loading="loading" :error="error" @retry="load"/><div v-if="post&&!loading&&!error" class="detail-layout"><article class="panel"><div class="row between"><span class="badge blue">{{post.post_type==='lost'?'寻物':'拾物'}}</span><span class="muted">第 {{post.revision}} 版</span></div><h1>{{post.item_name}}</h1><div class="row"><span class="badge" :class="post.resolution_status">{{resolution(post)}}</span><span v-if="owner" class="badge" :class="post.review_status">{{reviewLabels[post.review_status]}}</span></div><p class="muted">{{post.author.nickname}} · {{dateTime(post.first_published_at||post.submitted_at)}}</p><p v-if="post.review_reason" class="notice">审核说明：{{post.review_reason}}</p><PostContent :post="post" :images="post.image_urls"/><div class="form-actions" v-if="owner"><button v-if="post.can_complete" class="primary" :disabled="busy||conflict" @click="change(post.resolution_status==='completed'?'active':'completed')">{{post.resolution_status==='completed'?(post.post_type==='lost'?'恢复寻找中':'恢复待认领'):(post.post_type==='lost'?'标记已找回':'标记已归还')}}</button><a v-if="post.can_edit" :href="'#edit/'+post.id" class="secondary">编辑</a><button v-if="post.resolution_status!=='withdrawn'" class="danger" :disabled="busy||conflict" @click="open('withdraw')">撤回</button><p v-else class="notice">帖子已撤回，无法编辑或恢复。</p></div><div v-else-if="post.can_report" class="form-actions"><button class="text-button" :disabled="reported" @click="open('report')">{{reported?'举报已提交':'举报这条信息'}}</button></div><p v-if="actionError&&!modal" class="error" role="alert">{{actionError}}</p><button v-if="conflict" class="secondary" @click="load">重新查看最新状态</button></article><aside class="panel detail-aside" v-if="owner||session.user.role==='admin'"><h2>审核记录</h2><p v-if="!history.length" class="muted">暂无审核记录</p><article v-for="r in history" :key="r.id" class="timeline"><span class="badge" :class="r.decision">{{reviewLabels[r.decision]}}</span><h3>第 {{r.revision}} 版</h3><p class="fine">{{dateTime(r.processed_at||r.submitted_at)}}</p><p v-if="r.reason">{{r.reason}}</p><p v-if="r.decision==='superseded'" class="muted">内容更新后，旧待审记录已被取代。</p><button class="text-button" @click="snapshot=r">查看历史快照 →</button></article><div class="row"><button v-if="historyPage>1" @click="loadHistory(historyPage-1)">上一页</button><button v-if="historyPage*10<historyTotal" @click="loadHistory(historyPage+1)">下一页</button></div></aside><aside v-else class="panel detail-aside"><h3>每一次归还，都很温暖。</h3><p>联系前请确认物品特征，妥善安排交接时间和地点。</p><p class="fine">如内容存在问题，可通过举报反馈给管理员。</p></aside></div><Modal v-if="modal==='withdraw'" title="撤回这篇帖子？" :busy="busy" @close="modal=''"><p class="notice">{{post.item_name}}</p><p>撤回后帖子将隐藏，无法恢复或编辑。审核记录仍会保留。</p><p v-if="actionError" class="error">{{actionError}}</p><div class="form-actions"><button class="secondary" :disabled="busy" @click="modal=''">取消</button><button class="danger" :disabled="busy||conflict" @click="change('withdrawn')">确认撤回</button></div></Modal><Modal v-if="modal==='report'" title="举报这条信息" :busy="busy" @close="modal=''"><form @submit.prevent="report"><label>举报原因<select v-model="reason" required><option value="">请选择原因</option><option v-for="(label,key) in reasons" :value="key">{{label}}</option></select></label><label>补充说明 <small>其他原因必填</small><textarea v-model="details" rows="4"></textarea><small>{{[...details].length}} / 500</small></label><p class="fine">举报将关联你正在查看的第 {{post.revision}} 版内容。请如实填写。</p><p v-if="actionError" class="error">{{actionError}}</p><button class="primary" :disabled="busy">{{busy?'提交中…':'提交举报'}}</button></form></Modal><Modal v-if="snapshot" :title="'第 '+snapshot.revision+' 版 · 历史快照'" @close="snapshot=null"><p class="notice">历史内容仅供查看，不可编辑。</p><h2>{{snapshot.content_snapshot.item_name}}</h2><PostContent :post="snapshot.content_snapshot" :images="historyImages(snapshot)"/></Modal></template>
